describe('Example Page Navigation', () => {
  it('should navigate to the example page and back', () => {
    cy.visit('https://the-internet.herokuapp.com/examples');
    cy.get('a').contains('A/B Testing').click();
    cy.url().should('include', '/abtest');
    cy.get('h3').contains('A/B Testing').should('be.visible');
    cy.get('a').contains('Available Examples').click();
    cy.url().should('include', '/examples');
    cy.get('h3').contains('Available Examples').should('be.visible');
  });

  it('should not change URL when clicking the same link', () => {
    cy.visit('https://the-internet.herokuapp.com/examples');
    cy.get('a').contains('A/B Testing').click();
    cy.url().should('include', '/abtest');
    cy.get('a').contains('A/B Testing').click();
    cy.url().should('include', '/abtest');
  });
});
